/**
 * SystemInfo component.
 *
 * Renders server/PHP/WP environment details in a tabular layout.
 * Data is fetched on-demand when the user clicks "Load System Info"
 * rather than automatically on mount, to keep the Dashboard fast.
 *
 * @since 1.5.0
 */

import { useState, memo } from '@wordpress/element';
import { fetchSystemInfo } from '../lib/apiRequest';
import useNotice from '../lib/useNotice';
import FeatureCard from './common/FeatureCard';
import LoadingSubmitButton from './common/LoadingSubmitButton';
import NoticeBanner from './common/NoticeBanner';

import { __ } from '@wordpress/i18n';

/**
 * A single key-value row in a system info table.
 *
 * @param {Object} props
 * @param {string} props.label Row label.
 * @param {*}      props.value Row value (null renders as '—').
 */
const InfoRow = ( { label, value } ) => (
	<tr className="wppo-sysinfo-table__row">
		<td className="wppo-sysinfo-table__label">{ label }</td>
		<td className="wppo-sysinfo-table__value">
			{ value !== null && value !== undefined && value !== ''
				? String( value )
				: '—' }
		</td>
	</tr>
);

/**
 * A labelled table of InfoRow items.
 *
 * @param {Object} props
 * @param {string} props.title  Section heading.
 * @param {Object} props.data   Key-value pairs to render.
 * @param {Object} props.labels Optional map of data keys to display labels.
 */
const InfoTable = ( { title, data, labels = {} } ) => {
	if ( ! data ) {
		return null;
	}

	return (
		<div className="wppo-sysinfo-section">
			<h4 className="wppo-sysinfo-section__title">{ title }</h4>
			<table className="wppo-sysinfo-table">
				<tbody>
					{ Object.entries( data ).map( ( [ key, value ] ) => (
						<InfoRow
							key={ key }
							label={ labels[ key ] || key }
							value={ value }
						/>
					) ) }
				</tbody>
			</table>
		</div>
	);
};

const SystemInfo = () => {
	const [ info, setInfo ] = useState( null );
	const [ loading, setLoading ] = useState( false );
	const [ loaded, setLoaded ] = useState( false );
	const { notice, notify, dismiss } = useNotice();

	const handleLoad = async () => {
		setLoading( true );
		dismiss();

		try {
			const response = await fetchSystemInfo();
			if ( response.success && response.data ) {
				setInfo( response.data );
				setLoaded( true );
			} else {
				notify( {
					type: 'error',
					message:
						response.message ||
						__(
							'Failed to fetch system info. Please try again.',
							'performance-optimisation'
						),
				} );
			}
		} catch ( err ) {
			notify( {
				type: 'error',
				message: __(
					'Failed to fetch system info. Please try again.',
					'performance-optimisation'
				),
			} );
			console.error( 'System info fetch error:', err );
		} finally {
			setLoading( false );
		}
	};

	return (
		<FeatureCard title={ __( 'System Info', 'performance-optimisation' ) }>
			{ /* Load trigger — shown to initiate fetch or refresh data */ }
			<div
				className={ `wppo-sysinfo-trigger ${
					loaded ? 'wppo-sysinfo-trigger--compact' : ''
				}` }
			>
				{ ! loaded && ! notice && (
					<p
						id="wppo-sysinfo-desc"
						className="wppo-sysinfo-trigger__desc"
					>
						{ __(
							'View PHP, database, WordPress, and server environment details.',
							'performance-optimisation'
						) }
					</p>
				) }
				<LoadingSubmitButton
					type="button"
					className="wppo-button wppo-button--secondary"
					onClick={ handleLoad }
					aria-describedby={
						! loaded && ! notice ? 'wppo-sysinfo-desc' : undefined
					}
					isLoading={ loading }
					label={
						loaded
							? __( 'Refresh', 'performance-optimisation' )
							: __(
									'Load System Info',
									'performance-optimisation'
							  )
					}
					loadingLabel={ __(
						'Loading…',
						'performance-optimisation'
					) }
				/>
			</div>

			{ /* Error state */ }
			{ notice && (
				<NoticeBanner type={ notice.type } message={ notice.message } />
			) }

			{ /* Results — two-column grid of tables */ }
			{ info && (
				<div className="wppo-sysinfo-grid">
					<InfoTable
						title={ __( 'PHP', 'performance-optimisation' ) }
						data={ info.php }
						labels={ {
							version: __(
								'PHP Version',
								'performance-optimisation'
							),
							sapi: __( 'SAPI', 'performance-optimisation' ),
							memory_limit: __(
								'Memory Limit',
								'performance-optimisation'
							),
							max_execution_time: __(
								'Max Execution Time',
								'performance-optimisation'
							),
							upload_max_filesize: __(
								'Upload Max Filesize',
								'performance-optimisation'
							),
							post_max_size: __(
								'Post Max Size',
								'performance-optimisation'
							),
							display_errors: __(
								'Display Errors',
								'performance-optimisation'
							),
							extensions_count: __(
								'Extensions Loaded',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __( 'Database', 'performance-optimisation' ) }
						data={ info.database }
						labels={ {
							server_version: __(
								'DB Version',
								'performance-optimisation'
							),
							extension: __(
								'Extension',
								'performance-optimisation'
							),
							client_version: __(
								'Client Version',
								'performance-optimisation'
							),
							max_connections: __(
								'Max Connections',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __( 'WordPress', 'performance-optimisation' ) }
						data={ info.wordpress }
						labels={ {
							version: __(
								'WP Version',
								'performance-optimisation'
							),
							environment_type: __(
								'Environment',
								'performance-optimisation'
							),
							permalink_structure: __(
								'Permalink Structure',
								'performance-optimisation'
							),
							using_https: __(
								'HTTPS',
								'performance-optimisation'
							),
							multisite: __(
								'Multisite',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __( 'Server', 'performance-optimisation' ) }
						data={ info.server }
						labels={ {
							server_software: __(
								'Server Software',
								'performance-optimisation'
							),
							os: __(
								'Operating System',
								'performance-optimisation'
							),
							architecture: __(
								'Architecture',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __( 'Cache', 'performance-optimisation' ) }
						data={ {
							object_cache_status:
								info.cache?.object_cache_status,
							active_cache_plugin:
								info.cache?.active_cache_plugin,
							peak_memory_usage: info.cache?.peak_memory_usage,
							current_memory_usage:
								info.cache?.current_memory_usage,
						} }
						labels={ {
							object_cache_status: __(
								'Object Cache',
								'performance-optimisation'
							),
							active_cache_plugin: __(
								'Active Cache Plugin',
								'performance-optimisation'
							),
							peak_memory_usage: __(
								'Peak Memory',
								'performance-optimisation'
							),
							current_memory_usage: __(
								'Current Memory',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __( 'OPCache', 'performance-optimisation' ) }
						data={ info.opcache }
						labels={ {
							status: __( 'Status', 'performance-optimisation' ),
							memory_usage: __(
								'Memory Usage',
								'performance-optimisation'
							),
							interned_strings: __(
								'Interned Strings',
								'performance-optimisation'
							),
							hit_rate: __(
								'Hit Rate',
								'performance-optimisation'
							),
							cache_full: __(
								'Cache Full',
								'performance-optimisation'
							),
							detail: __( 'Detail', 'performance-optimisation' ),
						} }
					/>
					<InfoTable
						title={ __(
							'Infrastructure',
							'performance-optimisation'
						) }
						data={ {
							action_scheduler: info.infrastructure
								?.action_scheduler?.available
								? __( 'Available', 'performance-optimisation' )
								: __(
										'Unavailable',
										'performance-optimisation'
								  ),
							pagespeed_api: info.infrastructure?.pagespeed_api
								?.configured
								? __( 'Configured', 'performance-optimisation' )
								: __(
										'Not Configured',
										'performance-optimisation'
								  ),
						} }
						labels={ {
							action_scheduler: __(
								'Action Scheduler',
								'performance-optimisation'
							),
							pagespeed_api: __(
								'PageSpeed Insights API',
								'performance-optimisation'
							),
						} }
					/>
					<InfoTable
						title={ __(
							'WP Constants',
							'performance-optimisation'
						) }
						data={ info.wp_constants }
					/>
				</div>
			) }
		</FeatureCard>
	);
};

export default memo( SystemInfo );
